
<style>
    
</style>

<script>
    import { wTrans } from 'laravel-vue-i18n';
    import Plib from '@/lib/pickle';
    import { useRoute } from 'vue-router';
    import { useAuthStore } from '@/stores/auth';

    import { useNavigationStore } from '@/stores/navigation';
    import { useFormDataStore } from '@/stores/formdata';
    import Swal from 'sweetalert2';
    
    import CoalForm from '@/components/coalparts/Form.vue';


    export default {
        breadcrumbs: {
            list: [  { title: 'Kullanıcılar', path: '/coalpanel/users' } ],
            title: 'Kullanıcı Düzenle / Oluştur'
        },
        components: {
            CoalForm,
        },
        setup() {
            // expose to template and other options API hooks
            return {
                useNavigationStore,
                useFormDataStore,
                Plib,
                Swal,
                useRoute,
                wTrans
            }
        },
        mounted(){
            this.navigationStore.toggle(true);
            
            const checkData = async () => {
                //if has id param get document data first
                if(this.id !== undefined && this.id !== ''){
                    const rsp = await this.plib.request({
                        url      : '/api/v1/persons/'+this.id,
                        method   : 'GET',
                    },null);
                    return rsp;
                }else{
                    return {
                        success : false
                    }
                }
            }

            checkData().then(response => {
                this.navigationStore.toggle(true);
                if(response?.data){
                    response.data.user_username = response?.data.user_name;
                    response.data.main_name     = response?.data.name;
                    response.data.user_status   = response?.data.user_status;
                }   
                //here set permissions options
                let permissions = JSON.parse(response?.data?.permissions ?? '[]');

                if (permissions?.length > 0) {
                    try {
                        response.data.permissions = JSON.parse(permissions[0].Value);
                    } catch (e) {
                        response.data.permissions = permissions[0].Value;
                    }
                }
                //set ready data do store for update transactions (form component will catch that)
                this.formDataStore.setData({
                    'op-doc-user-form' : {
                        [this.id] : {
                            'entities' : response?.data
                        }
                    }
                });
                
                //here set facility options
                let contacts = JSON.parse(response?.data?.contacts ?? '[]');
                if(contacts.length > 0){
                    contacts.forEach(obj => response.data[obj.Key] = obj.Value);
                    this.formDataStore.setData({
                        'op-doc-user-form' : {
                            [this.id] : {
                                'entities' : response?.data
                            }
                        }
                    });
                }

                let clients = JSON.parse(response?.data?.clients ?? '[]');
                
                if(clients.length > 0){
                    clients.forEach(obj => response.data[obj.Key] = obj.Value);
                    this.formDataStore.setData({
                        'op-doc-user-form' : {
                            [this.id] : {
                                'entities' : response?.data
                            }
                        }
                    });
                }

                this.loadForm = true;
                
                setTimeout(() => {
                    this.navigationStore.toggle(false);
                }, 500);
                
            });

           
        },  
        data() {
            const route = useRoute();
            return {
                formKey         : 'op-doc-user',
                loadForm        : false,
                plib            : new Plib(),
                navigationStore : useNavigationStore(),
                authStore       : useAuthStore(),
                formDataStore   : useFormDataStore(),
                id              : route?.params?.id !== '' ? route?.params?.id : undefined,
            };
        },
        methods: {
            
            /**
             * Kaydetme basarili olduktan sonra uretilen parolayi gosterir.
             * Zamanlayici yok: yonetici kopyalayip kendisi kapatir.
             */
            async showGeneratedPassword(password){
                //Kopyala kendi dugmemiz: SweetAlert'in cancel dugmesini kullansaydik
                //tiklama modali kapatirdi ve bunu engellemek olay yayilimiyla ugrasmayi gerektirirdi
                await Swal.fire({
                    icon  : 'success',
                    title : 'Kullanıcı kaydedildi',
                    html  : `<p class="mb-3">Üretilen parola aşağıdadır. Kapatmadan önce kopyalayın —
                                bu ekran kapandıktan sonra parola bir daha gösterilmeyecektir.</p>
                             <input id="generatedPassword" class="form-control text-center fs-4 fw-bold"
                                    value="${password}" readonly>
                             <button id="copyPasswordBtn" type="button" class="btn btn-secondary mt-3">
                                <i class="ki-outline ki-copy fs-3 me-1"></i> Kopyala
                             </button>
                             <small id="copyFeedback" class="text-success d-block mt-2" style="visibility:hidden;">Kopyalandı</small>`,
                    confirmButtonText : 'Kapat',
                    allowOutsideClick : false,
                    allowEscapeKey    : false,
                    didOpen : () => {
                        const field    = document.getElementById('generatedPassword');
                        const feedback = document.getElementById('copyFeedback');

                        document.getElementById('copyPasswordBtn').addEventListener('click', async () => {
                            try {
                                await navigator.clipboard.writeText(password);
                            } catch (err) {
                                //clipboard API yalnizca guvenli baglamda calisir; degilse secimle kopyala
                                field.select();
                                document.execCommand('copy');
                            }

                            field.select();
                            feedback.style.visibility = 'visible';
                        });
                    },
                });
            },
            async submitForm(formData){
                this.formData = formData;
                this.navigationStore.toggle(true);
                this.formData.typeKey = 'op-pert-admin';
                const rsp = this.plib.checkForm('.form-item');
                if(rsp.valid){

                    //check pass
                    const fields = Object.values(this.formData.dynamicF)[0]?.entities;
                    //here check if username is entered but password is empty
                    if(fields?.user_username != undefined && (fields?.user_password == undefined || fields?.user_password == '')){
                        this.navigationStore.toggle(false);
                        this.plib.toast(this.Swal,'error','Parola alanı boş bırakılamaz..',);
                        document.querySelector('input[name="user_password"]').classList.add('is-invalid');
                        return false;
                    }


                    //here check password rules
                    if(fields?.user_password !== undefined){
                        const valid = fields?.user_password.match(
                            /^(?=.{8,}$)(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[=!\-@._*])[A-Za-z0-9=!\-@._*]+$/
                        ) != null;
                        if(!valid){
                            this.navigationStore.toggle(false);
                            this.plib.toast(this.Swal,'error',`Şifreniz en az bir tane büyük/küçük harf, rakam
                                            ve özel karakter
                                            içermelidir ve 8 karakterden oluşmalıdır.`,);
                            document.querySelector('input[name="user_password"]').classList.add('is-invalid');
                            return false;
                        }
                    }



                    //here check passwords
                    if(fields?.user_password){
                        
                        if(fields?.user_password_check == undefined || fields?.user_password != fields?.user_password_check){
                            this.navigationStore.toggle(false);
                            this.plib.toast(this.Swal,'error','Parola alanları uyuşmamaktadır..',);
                            document.querySelector('input[name="user_password"]').classList.add('is-invalid');
                            document.querySelector('input[name="user_password_check"]').classList.add('is-invalid');
                            return false;
                        }
                    }
                    if(this.formData.permissions){
                        fields.permissions = this.formData.permissions.map(el => el.op_key);
                        //fields.permissions
                    }
                    
                    const   envelope  = new FormData();
                        envelope.append('data',JSON.stringify(fields));
                        envelope.append('alldata',JSON.stringify(this.formData));
                    //register files
                    for(let key in this.formData.files){
                        const fileItem = this.formData.files[key];
                        if(fileItem && !fileItem.uploading && fileItem.reference){
                            envelope.append(key, JSON.stringify(fileItem.reference));
                        } else if(fileItem && fileItem.file) {
                            envelope.append(key, fileItem.file);
                        }
                    }
                    const rsp = await this.plib.request({
                        url      : '/api/v1/users'+(this.id !== undefined ? '/'+this.id : ''),
                        method   : this.id !== undefined ? 'PUT' : 'POST',
                    },null,envelope);

                    //backend basarisiz olsa bile basari mesaji gosterilip listeye
                    //yonlendiriliyordu; yonetici sifreyi degistirdim saniyordu
                    if(!rsp?.success){
                        this.navigationStore.toggle(false);
                        this.plib.toast(
                            this.Swal,
                            'error',
                            rsp?.msg ?? rsp?.data?.message ?? 'Kullanıcı kaydedilemedi. Lütfen bilgileri kontrol edip tekrar deneyin.'
                        );
                        return;
                    }

                    this.navigationStore.toggle(false);

                    const goOn = () => {
                        if(this.authStore.permissions?.includes('per-04-01')){
                            this.$router.push({ name: 'UList' });
                        }else{
                            window.location.reload();
                        }
                    };

                    //parola yalnizca uretici kullanildiysa gosteriliyor; elle yazilmissa
                    //yonetici zaten biliyor
                    if(this.formData.passwordGenerated && fields?.user_password){
                        await this.showGeneratedPassword(fields.user_password);
                        goOn();
                        return;
                    }

                    setTimeout(() => {
                        this.plib.toast(this.Swal,'success','İşlem Tamamlandı',goOn);
                    }, 300);

                }else{
                    this.navigationStore.toggle(false);
                    this.plib.toast(this.Swal,'info','Eksik Alanları Doldurmalısınız..',() => {});
                }
            },

        }
    }

</script>

<template>
    <CoalForm :formtypes="formKey+'-form'" v-if="loadForm" :savecallback="submitForm" />
</template>
